@startuml

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Employee {
  + socialSecurityNumber : string
  + name : string
  + emailAddress : string
}

class ResearchAssistant extends Employee {
  + fieldOfResearch : string
}

class Lecturer extends ResearchAssistant {}

class AdministrativeStaff extends Employee {}

class Project {
  + name : string
  + startDate : date
  + endDate : date
}

class Course {
  + ID : int
  + name : string
  + weeklyDuration : int
}

class RAProjectAssignment {
  + hours : int
}

Faculty "1" -- "*" Institute : consists of
Faculty "1" -- "1" Employee : headed by
Employee "1" -- "*" Employee : total number of employees
ResearchAssistant "*" -- "1..*" Institute : assigned to
ResearchAssistant "1" -- "*" RAProjectAssignment : involved in
RAProjectAssignment "*" -- "1" Project : for
Lecturer "1" -- "*" Course : teaches

@enduml

